INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob firmeneigene Infos immer in einer Datenbank gespeichert werden müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien oder Cloud möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode schützt sensible Unternehmensdaten vor unbefugtem Zugriff?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Macht Daten unlesbar"}, {"text": "Schnelle Hardware", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nur Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern firmeneigene Informationen?', 5, '[{"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzen Zugang"}, {"text": "Backups", "correct": true, "because": "Schützen vor Verlust"}, {"text": "Firewall", "correct": true, "because": "Blockiert Angriffe"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschlüsselung schützt bei Übertragung. b) Alle Mitarbeiter brauchen vollen Zugriff.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erhöht Risiken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Unternehmensdaten verwalte?', 4, '[{"text": "Datenschutz", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Sicherung", "correct": false, "because": "Schützt vor Verlust"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass firmeneigene Infos immer lokal gespeichert werden müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Cloud möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft mir, Unternehmensdaten zu sichern?', 3, '[{"text": "Backup-Software", "correct": true, "because": "Speichert Kopien"}, {"text": "Texteditor", "correct": false, "because": "Kein Sicherungstool"}, {"text": "Browser", "correct": false, "because": "Nur Anzeige"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen die Verwaltung von Firmendaten effektiv?', 5, '[{"text": "Zugriffsrechte", "correct": true, "because": "Begrenzen Zugriff"}, {"text": "Datenintegrität", "correct": true, "because": "Sichert Korrektheit"}, {"text": "Regelmäßige Updates", "correct": true, "because": "Schützen System"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) interne Daten verschlüsselt werden sollten und b) sie öffentlich sein dürfen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht Schutz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Unternehmensdaten zu schützen?', 4, '[{"text": "Firewall", "correct": false, "because": "Blockiert Angriffe"}, {"text": "Verschlüsselung", "correct": false, "because": "Sichert Daten"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind interne Daten immer in der Cloud sicher?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Anbieter"}, {"text": "Ja", "correct": false, "because": "Risiken bestehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen Firmendaten vor Verlust?', 4, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglichen Wiederherstellung"}, {"text": "Offsite-Speicherung", "correct": true, "because": "Schützt vor physischem Schaden"}, {"text": "Schnelle Hardware", "correct": false, "because": "Nur Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Unternehmensdaten nur lokal sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Cloud mit Schutz möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel sicherbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Verwaltung von Firmendaten?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schützt Informationen"}, {"text": "Designverbesserung", "correct": false, "because": "Sekundär"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zugriffskontrollen schützen Daten. b) Datenintegrität ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrität essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um Unternehmensdaten zu verschlüsseln?', 4, '[{"text": "AES", "correct": true, "because": "Starker Standard"}, {"text": "FTP", "correct": false, "because": "Übertragung"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob interne Daten immer physisch gespeichert werden müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Cloud möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Datenbank für Firmendaten?', 5, '[{"text": "Strukturierte Speicherung", "correct": true, "because": "Organisiert Daten"}, {"text": "Schneller Zugriff", "correct": true, "because": "Effiziente Abfragen"}, {"text": "Sicherheitsfunktionen", "correct": true, "because": "Schützt Zugriff"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind interne Daten immer öffentlich zugänglich?', 3, '[{"text": "Nein", "correct": true, "because": "Schutz nötig"}, {"text": "Ja", "correct": false, "because": "Vertraulichkeit wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Verwaltung von Firmendaten?', 4, '[{"text": "Mitarbeiterdaten sichern", "correct": true, "because": "Typische Anwendung"}, {"text": "Webseitenlayout", "correct": false, "because": "Anderer Zweck"}, {"text": "Datenkompression", "correct": false, "because": "Sekundär"}]');
